// =============================================================================
// blake3_tree_tb.v — differential test of blake3_tree.v vs. reference BLAKE3
// =============================================================================
//
// Drives blake3_tree.v with an 8 KB byte buffer pre-loaded from a hex file
// generated by host/src/bin/blake3_tree_gen.rs. Captures the 256-bit output
// and compares against the Rust reference (also written by the generator).
//
// PASS proves: byte/word order, IV constants, CHUNK_START/CHUNK_END placement,
// per-chunk counter, PARENT/ROOT flag application, level-by-level CV pairing,
// and the full 135-compression state-machine sequencing all match the BLAKE3
// spec end-to-end.
//
// Run via scripts/test_blake3_tree.sh.
// =============================================================================

`timescale 1ns / 1ps

module blake3_tree_tb;

    // -------------------------------------------------------------------------
    // Clock + reset
    // -------------------------------------------------------------------------
    reg clk = 0;
    always #5 clk = ~clk;        // 100 MHz sim clock

    reg reset_n = 0;
    reg start   = 0;

    // -------------------------------------------------------------------------
    // Behavioral trng buffer — 8192 bytes loaded from generator output.
    // Read latency: 1 cycle, registered output (matches trng.v's BRAM exactly).
    // -------------------------------------------------------------------------
    wire [12:0] buf_raddr;
    reg  [7:0]  buf_rdata;
    reg  [7:0]  test_buf [0:8191];

    initial $readmemh("build/blake3_tree_test/blake3_tree_input.hex", test_buf);

    always @(posedge clk) buf_rdata <= test_buf[buf_raddr];

    // -------------------------------------------------------------------------
    // DUT
    // -------------------------------------------------------------------------
    wire [255:0] ira;
    wire         ira_valid;
    wire         busy;

    blake3_tree dut (
        .clk      (clk),
        .reset_n  (reset_n),
        .start    (start),
        .buf_raddr(buf_raddr),
        .buf_rdata(buf_rdata),
        .ira      (ira),
        .ira_valid(ira_valid),
        .busy     (busy)
    );

    // -------------------------------------------------------------------------
    // Reference hash — 32 hex bytes, one per line.
    // -------------------------------------------------------------------------
    reg [7:0]   expected_bytes [0:31];
    initial $readmemh("build/blake3_tree_test/blake3_tree_expected.hex", expected_bytes);

    wire [255:0] expected;
    genvar e;
    generate
        for (e = 0; e < 32; e = e + 1) begin : assemble_expected
            assign expected[8*e +: 8] = expected_bytes[e];
        end
    endgenerate

    // -------------------------------------------------------------------------
    // Stimulus + check
    // -------------------------------------------------------------------------
    integer start_time, end_time;

    initial begin
        // Optional VCD trace — useful when debugging mismatches.
        // $dumpfile("build/blake3_tree_test/blake3_tree.vcd");
        // $dumpvars(0, blake3_tree_tb);

        $display("");
        $display("=== blake3_tree.v differential test ===");
        $display("Input:    build/blake3_tree_test/blake3_tree_input.hex (8192 bytes)");
        $display("Expected: %h", expected);

        #25 reset_n = 1;
        #20 start   = 1;
        #10 start   = 0;

        start_time = $time;
        wait (ira_valid);
        end_time = $time;

        #1;
        $display("");
        $display("Got:      %h", ira);
        $display("Expected: %h", expected);
        $display("Latency:  %0d ns sim time (%0d cycles)",
                 end_time - start_time, (end_time - start_time) / 10);

        if (ira === expected) begin
            $display("");
            $display("  *** PASS ***  blake3_tree.v output matches reference BLAKE3");
        end else begin
            $display("");
            $display("  *** FAIL ***  output mismatch — see diff above");
            $display("              XOR: %h", ira ^ expected);
        end
        $display("");
        $finish;
    end

    // Safety timeout — at 100 MHz sim clock, full hash takes ~12 k cycles
    // = ~120 us. Anything over 1 ms means the FSM is stuck.
    initial begin
        #1_000_000;
        $display("");
        $display("  *** TIMEOUT ***  blake3_tree.v did not complete in 1 ms sim time");
        $finish;
    end

endmodule
